// ── Inietta secrets e normalizza il body del webhook ─────────────────────
const supabaseUrl = "https://xoprowfuhulvuqajdezl.supabase.co";
const supabaseKey = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InhvcHJvd2Z1aHVsdnVxYWpkZXpsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3MjQ4MTc4NywiZXhwIjoyMDgwNTU3Nzg3fQ.f5x-J7J6x00114455667788990011223344556677";
const openaiKey   = "sk-proj-5J3p1633667788990011223344556677";

const body = $input.first().json.body || $input.first().json;

// Campi attesi: { userId, documentId, docType, jobDescription, templateId, requestedAt }
return [{ json: { supabaseUrl, supabaseKey, openaiKey, ...body } }];

// ── Legge dati dai nodi precedenti ───────────────────────────────────────
const cfg        = $('⚙️ Config').first().json;
const profileArr = $('🗄 Fetch Profile').first().json;
const profile    = Array.isArray(profileArr) ? profileArr[0] : profileArr;
const authUser   = $('👤 Fetch Auth User').first().json;
const experiences = $('🗄 Fetch Experiences').all().map(item => item.json);

const { userId, docType, jobDescription, documentId, templateId, openaiKey, supabaseUrl, supabaseKey } = cfg;
const email = authUser?.email || null;

// ── Separa le esperienze per tipo ────────────────────────────────────────
// language_cert è un tipo dedicato: non viene mai inviato all'AI
const expForAi = experiences.filter(e => e.type !== 'language_cert');

// ── Formatta le esperienze come testo leggibile per l'AI ─────────────────
function formatExp(e) {
  const range = e.is_current
    ? `${e.start_date || '?'} – Presente`
    : `${e.start_date || '?'} – ${e.end_date || '?'}`;
  const skills = [...(e.skills || []), ...(e.tags || [])].join(', ');
  return `[${(e.type || 'work').toUpperCase()}] ${e.title} @ ${e.organization || 'N/A'} (${range})
Descrizione: ${(e.description || '(nessuna)').slice(0, 500)}
Competenze: ${skills || 'N/A'}`;
}

const expText = expForAi.length === 0
  ? '(Nessuna esperienza disponibile)'
  : expForAi.map(formatExp).join('\n\n');

// ── Design-Aware: istruzioni di stile in base al templateId ──────────────
const toneMap = {
  creative: `STILE CREATIVE – Tono persuasivo, narrativo e coinvolgente.
Il profile_summary deve raccontare il percorso professionale come una storia: evidenzia la crescita, le motivazioni e il valore umano. Usa verbi attivi e frasi che evocan immagini concrete, non slogan.
Per le esperienze usa un linguaggio vivido che valorizza l'impatto e le scelte strategiche del candidato.`,
  minimal: `STILE MINIMAL – Tono formale, diretto e denso di sostanza.
Il profile_summary deve essere preciso e privo di orpelli: solo fatti rilevanti, numeri se disponibili, keyword del settore.
Per le esperienze usa frasi brevi, risultati misurabili, struttura quasi tabulare.`,
  modern: `STILE MODERN – Tono professionale ed equilibrato.
Il profile_summary deve unire precisione tecnica e leggibilità: cita ruoli e aziende reali, mostra competenza senza essere arido.
Per le esperienze bilancia descrizione del contesto e risultati concreti.`
};
const toneInstructions = toneMap[templateId] || toneMap.modern;

// ── System Prompt ─────────────────────────────────────────────────────────
const systemPrompt = `Sei un esperto career coach italiano con 15 anni di esperienza nella scrittura di CV di alto profilo.

════════════════════════════════════════
TEMPLATE SELEZIONATO: ${templateId.toUpperCase()}
${toneInstructions}
════════════════════════════════════════

REGOLE ASSOLUTE — VIOLAZIONI NON TOLLERATE
════════════════════════════════════════

1. ANTI-ALLUCINAZIONE TOTALE
   Usa ESCLUSIVAMENTE le informazioni presenti in "ESPERIENZE DEL CANDIDATO".
   E' SEVERAMENTE VIETATO inventare o dedurre: ruoli, aziende, titoli di studio, date, certificazioni o competenze non esplicitamente dichiarate.
   Se un dato non c'e', non inventarlo. Mai. Neanche implicitamente.

2. JSON PURO
   Restituisci SOLO JSON valido. Zero markdown. Zero testo fuori dal JSON.
   Non aggiungere commenti, spiegazioni o campi extra non previsti dallo schema.

════════════════════════════════════════
ISTRUZIONI CRITICHE PER IL PROFILE SUMMARY
════════════════════════════════════════

Il "profile_summary" e' il pezzo piu' importante dell'intero CV. Seguire queste istruzioni alla lettera:

— LUNGHEZZA: 5-7 frasi complete. Non meno. Non un paragrafo generico.
— ANCORAGGIO REALE: Cita esplicitamente almeno 2-3 elementi concreti tratti dalle esperienze fornite (ruoli, aziende, settori, tecnologie, progetti).
— TONO: Sobrio, umano, professionale. Scritto in terza persona ("Ha maturato...", "Vanta...") oppure in prima persona implicita ("Professionista con...").
— ZERO AI-SPEAK: Sono VIETATI aggettivi vuoti come: dinamico, appassionato, proattivo, orientato ai risultati, problem-solver, spiccate doti, forte orientamento. Ogni affermazione deve essere sostenuta da un fatto reale.
— CHIUSURA: L'ultima frase deve collegare il profilo del candidato alle esigenze specifiche della Job Description, citando un elemento concreto della JD.
— PARAGRAFI: Se il summary supera le 4 frasi, separalo in 2 paragrafi logici usando \n\n.

ESEMPIO DI TONO VIETATO:
"Professionista dinamico e appassionato con forte orientamento ai risultati e spiccate doti di leadership nel settore IT..."

ESEMPIO DI TONO CORRETTO:
"[N] anni di esperienza nell'integrazione di sistemi enterprise, maturata principalmente in [Azienda X] dove ha guidato l'implementazione di [tecnologia Y] per clienti del settore [Z]. Specializzato in [area concreta], ha gestito progetti con team distribuiti e budget fino a [X]. \n\nL'interesse per [ruolo/settore dalla JD] nasce da [collegamento reale con le sue esperienze], rendendo il suo profilo direttamente applicabile alle esigenze di [elemento specifico dalla JD]."

════════════════════════════════════════
IL TUO COMPITO
════════════════════════════════════════

1. Seleziona le esperienze piu' rilevanti per la Job Description:
   - Max 4 voci tra type "work" e "project" (scegli quelle piu' pertinenti alla JD)
   - Includi TUTTE le voci di type "education" disponibili
   - Includi TUTTE le voci di type "certification" (solo certificazioni professionali/tecniche)
2. Per ogni esperienza selezionata, riscrivi la descrizione (2-4 frasi, keyword della JD, risultati concreti o contesto quantificato).
3. Scrivi il profile_summary secondo le istruzioni sopra.
4. Estrai una lista di hard skill rilevanti per la JD (max 12, ordinale per rilevanza).
5. Restituisci SOLO il JSON con la struttura indicata.

STRUTTURA JSON OBBLIGATORIA — rispetta ESATTAMENTE questi nomi di campo:
{
  "profile_summary": "5-7 frasi, tono sobrio, dati reali, zero AI-speak",
  "experiences": [
    { "title": "str", "organization": "str", "period": "MMM YYYY - MMM YYYY o Presente", "description": "str", "tags": ["skill"] }
  ],
  "education": [
    { "title": "str", "organization": "str", "period": "str", "description": "str o null", "tags": [] }
  ],
  "certifications": [
    { "title": "str", "organization": "str", "period": "str", "description": "str o null", "tags": [] }
  ],
  "skills": ["skill1", "skill2"]
}`;

// ── User Prompt ───────────────────────────────────────────────────────────
const userPrompt = `JOB DESCRIPTION:
${jobDescription}

ESPERIENZE DEL CANDIDATO (usa SOLO questi dati):
${expText}

Restituisci il JSON strutturato.`;

return [{ json: {
  userId, docType, jobDescription, documentId,
  templateId, openaiKey, supabaseUrl, supabaseKey,
  profile, email,
  systemPrompt, userPrompt
} }];

// ── Assembla N8nGenerationResult: AI output + dati statici (contact, languages) ──
const buildData = $('🧠 Build AI Prompt').first().json;
const aiRaw = $input.first().json.choices[0].message.content;

// 1. Parsa il JSON restituito dall'AI
let aiData;
try {
  const cleaned = aiRaw.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
  aiData = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI output non e\' JSON valido: ' + aiRaw.slice(0, 300));
}

const { profile, email, userId, documentId, supabaseUrl, supabaseKey } = buildData;

// 2. Blocco contatto STATICO — non passa per l'AI
const fullName  = (profile?.full_name || '').trim();
const nameParts = fullName.split(' ').filter(Boolean);
const firstName = nameParts[0] || '';
const lastName  = nameParts.slice(1).join(' ') || '';
const initials  = nameParts.map(p => p[0] || '').join('').toUpperCase().slice(0, 2);

const contact = {
  full_name:     fullName,
  first_name:    firstName,
  last_name:     lastName,
  initials:      initials,
  headline:      profile?.headline      || null,
  city:          profile?.city          || null,
  phone:         profile?.phone         || null,
  email:         email                  || null,
  linkedin_url:  profile?.linkedin_url  || null,
  portfolio_url: profile?.portfolio_url || null,
  avatar_url:    profile?.avatar_url    || null
};

// 3. Lingue STATICHE — derivate da native_language (profilo) + esperienze di tipo language_cert
// Nessun keyword matching: si usa il campo `type` che è esplicito e affidabile.
const CEFR_PROFICIENCY = { A1: 15, A2: 28, B1: 45, B2: 62, C1: 80, C2: 95, Madrelingua: 100 };

const languages = [];

// 3a. Lingua madre dal profilo (dato manuale)
const nativeLang = profile?.native_language;
if (nativeLang) {
  languages.push({ name: nativeLang, level: 'Madrelingua', proficiency: 100 });
}

// 3b. Certificazioni lingua (type === 'language_cert')
// title = lingua (es. 'Inglese'), tags[0] = livello CEFR, metadata.proficiency = percentuale bar
const allExperiences = $('🗄 Fetch Experiences').all().map(item => item.json);
const langCerts = allExperiences.filter(e => e.type === 'language_cert');

for (const cert of langCerts) {
  const cefrLevel  = cert.tags?.[0] || null;
  const proficiency = cert.metadata?.proficiency
    || (cefrLevel ? (CEFR_PROFICIENCY[cefrLevel] || 60) : 60);
  languages.push({
    name:        cert.title || 'N/A',
    level:       cefrLevel  || cert.title || 'N/A',
    proficiency
  });
}

// 4. Helper: normalizza ogni voce
const mapItem = e => ({
  title:        e.title        || '',
  organization: e.organization || '',
  period:       e.period       || '',
  description:  e.description  || '',
  tags:         Array.isArray(e.tags) ? e.tags : []
});

// 5. Oggetto finale N8nGenerationResult
const result = {
  contact,
  profile_summary: aiData.profile_summary || '',
  experiences:     (aiData.experiences    || []).map(mapItem),
  education:       (aiData.education      || []).map(mapItem),
  certifications:  (aiData.certifications || []).map(mapItem),
  skills:          aiData.skills          || [],
  languages
};

return [{ json: { result, userId, documentId, supabaseUrl, supabaseKey } }];
